/* Run with jsdom available on NODE_PATH; fixture is generated by the backend suite. */
const {JSDOM}=require(process.env.NOVALIS_JSDOM_MODULE||'jsdom'),assert=require('node:assert/strict'),fs=require('node:fs');
const fixture=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
(async()=>{
 const dom=new JSDOM('<div id="main-nav"></div><div id="view-actions"></div><div id="view-content"></div>',{url:'https://app.novalis.test/os/',runScripts:'outside-only'}),w=dom.window;
 w.eval(fs.readFileSync(require('node:path').join(__dirname,'../web/billing.js'),'utf8'));
 let role='manager',lastModal,calls=[],notifications=[];
 const api=async(path,method='GET',body)=>{calls.push({path,method,body});if(path==='/api/billing/setup')return fixture.setup;if(path==='/api/billing'&&method==='GET')return fixture.list;if(path==='/api/billing'&&method==='POST')return {id:fixture.document.id};if(path==='/api/billing/'+fixture.document.id)return {document:fixture.document};return {ok:true};};
 const ctx={api,state:{user:{role},view:'billing'},title(){w.document.getElementById('view-actions').replaceChildren();},toast:m=>notifications.push(m),modal:(...args)=>lastModal=args,openDialog(){},button:(name,fn,host)=>{const b=w.document.createElement('button');b.textContent=name;b.addEventListener('click',fn);host.append(b);},paymentOptions(){}};
 await w.NovalisBilling.mount(ctx);assert.match(w.document.body.textContent,/Facturé TTC/);assert.match(w.document.body.textContent,/Créer une facture/);
 fixture.list.default_mode='test';await w.NovalisBilling.mount(ctx);
 assert.equal(w.document.querySelector('[data-bill-mode="test"]').getAttribute('aria-pressed'),'true');
 assert.match(w.document.querySelector('.bill-stats').textContent,/Règlements simulés/);
 assert.equal(w.document.querySelector('.bill-stats strong').textContent,new Intl.NumberFormat('fr-BE',{style:'currency',currency:'EUR'}).format(fixture.list.test_totals.invoiced_cents/100));
 w.document.querySelector('[data-bill-mode="live"]').click();await new Promise(r=>setTimeout(r,20));
 assert.equal(w.document.querySelectorAll('[data-bill-open]').length,fixture.list.items.filter(i=>!i.test_mode).length*2);
 fixture.list.default_mode='live';await w.NovalisBilling.mount(ctx);
 assert.equal(w.document.querySelector('[data-bill-mode="live"]').getAttribute('aria-pressed'),'true');
 await w.NovalisBilling.create(ctx);const form=w.document.getElementById('bill-editor');assert.ok(form);const desc=form.querySelector('[data-field="description"]');desc.value='Audit du système';form.querySelector('[data-field="price"]').value='200';w.document.getElementById('bill-add-line').click();const second=form.querySelectorAll('.bill-line')[1];second.querySelector('[data-field=description]').value='Deuxième prestation';second.querySelector('[data-field=price]').value='50';form.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,30));
 const saved=calls.find(c=>c.method==='POST'&&c.path==='/api/billing');assert.ok(saved);assert.equal(saved.body.recipient.name,fixture.setup.projects[0].client_name);assert.equal(saved.body.lines[0].unit_cents,20000);assert.equal(saved.body.lines.length,2);assert.equal(saved.body.lines[1].unit_cents,5000);
 ctx.state.user.role='client';await w.NovalisBilling.mount(ctx);assert.doesNotMatch(w.document.getElementById('view-actions').textContent,/Créer une facture|Paramètres/);
 await w.NovalisBilling.open(fixture.document.id);assert.match(w.document.body.textContent,/Télécharger la facture PDF/);assert.match(w.document.body.textContent,/Télécharger le reçu/);assert.doesNotMatch(w.document.body.textContent,/Confirmer un virement reçu|Demander le paiement/);
 [...w.document.querySelectorAll('button')].find(b=>b.textContent==='Tester un paiement').click();assert.match(lastModal[0],/aucun débit/);assert.ok(lastModal[1].find(f=>f.name==='outcome'));
 await lastModal[2]({method:'bancontact',amount:10,outcome:'failed',confirm:true});assert.ok(calls.find(c=>c.path.endsWith('/simulate')&&c.body.amount_cents===1000&&c.body.outcome==='failed'));
 console.log('Billing UI: editor, recipient selection, amounts, client permissions, PDF links and simulation passed.');dom.window.close();
})().catch(e=>{console.error(e);process.exit(1);});
